  // The line: 170 hex digits after "T".
  wire [679:0] line = {3'b0, n, s1_sg, 2'b0, s1_a0, 2'b0, s1_b0, 2'b0, s1_a1, 2'b0, s1_b1, 2'b0, s1_c, s2_sg, 2'b0, s2_a0, 2'b0, s2_b0, 2'b0, s2_a1, 2'b0, s2_b1, 2'b0, s2_c, 2'b0, a0_r, a0_f, 2'b0, b0_r, b0_f, 2'b0, a1_r, a1_f, 2'b0, b1_r, b1_f, 2'b0, a2_r, a2_f, 2'b0, b2_r, b2_f};
  reg [679:0] held = 0;
  function [7:0] hex(input [3:0] v);
    hex = v < 10 ? 8'h30 + v : 8'h37 + v;
  endfunction
  reg [7:0] ci = 0;
  reg [7:0] ch;
  always @* begin
    if (ci == 0) ch = "T";
    else if (ci < 171) ch = hex(held[679 - 4 * (ci - 1) -: 4]);
    else if (ci == 171) ch = 8'h0d;
    else ch = 8'h0a;
  end
  localparam SHIFT = 0, SETTLE = 1, PULSE = 2, HOLD = 3, SEND = 4;
  reg [2:0] state = SHIFT;
  reg [8:0] k = 0;
  reg tx = 1, busy = 0;
  reg [7:0] baud = 0;
  reg [3:0] bitn = 0;
  reg [9:0] shift = 10'h3ff;
  always @(posedge clk_25mhz) begin
    ce <= 0;
    case (state)
      SHIFT: begin  // 168 shifts: every operand bit is new
        l1 <= {l1[166:0], l1[167] ^ l1[165] ^ l1[152] ^ l1[150]};
        l2 <= {l2[165:0], l2[166] ^ l2[160]};
        k <= k + 1;
