            busy <= 0;
            if (ci == 172) begin
              ci <= 0;
              n <= n + 1;
              if (&n) begin l1 <= 168'h1; l2 <= 167'h1; end
              state <= SHIFT;
            end else ci <= ci + 1;
          end
        end else baud <= baud + 1;
      default: state <= SHIFT;
    endcase
  end
  assign ftdi_rxd = tx;
